using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        await scenario.EvaluateAsync(messages, response);
        await scenario.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        // Arrange
        var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUpQuestions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire."),
            new(ChatRole.Assistant, ".NET Aspire is a cloud-ready stack for building distributed applications."),
            new(ChatRole.User, "What are its main components?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        await scenario.EvaluateAsync(messages, response);
        await scenario.DisposeAsync();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
        };

        return new ReportingConfiguration(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), "evaluation-results"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(_chatClient));
    }
}

